INSERT INTO `wp_options` VALUES (154,'_site_transient_wp_plugin_dependencies_plugin_data','a:1:{s:14:\"auxin-elements\";a:35:{s:4:\"name\";s:45:\"Shortcodes and extra features for Phlox theme\";s:4:\"slug\";s:14:\"auxin-elements\";s:7:\"version\";s:7:\"2.17.22\";s:6:\"author\";s:59:\"<a href=\"https://profiles.wordpress.org/averta/\">averta</a>\";s:14:\"author_profile\";s:38:\"https://profiles.wordpress.org/averta/\";s:12:\"contributors\";a:2:{s:6:\"averta\";a:3:{s:7:\"profile\";s:38:\"https://profiles.wordpress.org/averta/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/2520cf699d4831304bd81f527a47fca986241371b11ac7caef8a0d4e8b39c122?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:6:\"averta\";}s:14:\"averta_support\";a:3:{s:7:\"profile\";s:46:\"https://profiles.wordpress.org/averta_support/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/a766eb909746e2820bb2320afded25b389c0b0b2652c7782c183fd6ed0b16024?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:14:\"averta support\";}}s:8:\"requires\";s:3:\"5.0\";s:6:\"tested\";s:5:\"7.0.4\";s:12:\"requires_php\";s:3:\"7.0\";s:16:\"requires_plugins\";a:0:{}s:6:\"rating\";i:42;s:7:\"ratings\";a:5:{i:5;i:2;i:4;i:0;i:3;i:0;i:2;i:0;i:1;i:5;}s:11:\"num_ratings\";i:7;s:11:\"support_url\";s:52:\"https://wordpress.org/support/plugin/auxin-elements/\";s:15:\"support_threads\";i:1;s:24:\"support_threads_resolved\";i:0;s:15:\"active_installs\";i:80000;s:12:\"last_updated\";s:21:\"2026-08-01 1:50pm GMT\";s:5:\"added\";s:10:\"2016-08-30\";s:8:\"homepage\";s:45:\"https://wordpress.org/plugins/auxin-elements/\";s:8:\"sections\";a:6:{s:11:\"description\";s:4753:\"<h4>Overview</h4>\n<p>This plugin adds plenty of premium functionalities to Phlox theme, such as one-click demo importer, plugin manager, new shortcodes, widgets, page builder elements as well as extra theme options to extend the functionality of that theme.</p>\n<blockquote>\n<p><a href=\"http://phlox.pro\" title=\"Live demo of Phlox Theme\" rel=\"nofollow ugc\">Demo on Phlox Theme</a> | <a href=\"https://docs.phlox.pro/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_content=auxin-elements-doc&amp;utm_term=documentation\" title=\"Phlox Core Elements documentation\" rel=\"nofollow ugc\">Documentation</a> | <a href=\"https://www.youtube.com/playlist?list=PL7X-1Jmy1jcdekHe6adxB81SBcrHOmLRS\" title=\"Watch all video tutorials\" rel=\"nofollow ugc\">Video tutorials</a> | <a href=\"http://help.averta.net/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_content=auxin-elements-supp&amp;utm_term=support\" title=\"Free support\" rel=\"nofollow ugc\">Support forum</a></p>\n</blockquote>\n<h4>Features</h4>\n<ul>\n<li>Elementor Page builder support (27 Exclusive Elements)</li>\n<li>Page builder Elements</li>\n<li>31 Exclusive Shortcodes</li>\n<li>Auxin Widgets</li>\n<li>Login page customization</li>\n<li>Custom CSS and Javascript fields</li>\n<li>Header layout and image customization</li>\n<li>Mega Menu</li>\n<li>Fullscreen Menu</li>\n<li>Menu Skins</li>\n<li>Various Blog Page templates</li>\n<li>Sticky Header</li>\n<li>Sticky Footer</li>\n<li>Fully Responsive</li>\n<li>Cross Browser IE8+ and Other Modern Browsers</li>\n</ul>\n<h4>Some demo sites by Phlox theme</h4>\n<ul>\n<li><a href=\"http://demo.phlox.pro/portfolio-minimal/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=25\" rel=\"nofollow ugc\">Minimal Portfolio</a></li>\n<li><a href=\"http://demo.phlox.pro/free-shop/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=29\" rel=\"nofollow ugc\">Modern Shop</a></li>\n<li><a href=\"http://demo.phlox.pro/realstate/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=44\" rel=\"nofollow ugc\">Real State</a></li>\n<li><a href=\"http://demo.phlox.pro/architect/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=41\" rel=\"nofollow ugc\">The Architect</a></li>\n<li><a href=\"http://demo.phlox.pro/minimal-photography/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=28\" rel=\"nofollow ugc\">Minimal Photography</a></li>\n<li><a href=\"http://demo.phlox.pro/journey/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=6\" rel=\"nofollow ugc\">Journey Blog</a></li>\n<li><a href=\"http://demo.phlox.pro/classic-blog/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=7\" rel=\"nofollow ugc\">Classic Blog</a></li>\n<li><a href=\"http://demo.phlox.pro/portfolio/vivid/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=32\" rel=\"nofollow ugc\">Portfolio Vivid</a></li>\n<li><a href=\"http://demo.phlox.pro/portfolio/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=10\" rel=\"nofollow ugc\">Classic Portfolio</a></li>\n<li><a href=\"http://demo.phlox.pro/food/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=2\" rel=\"nofollow ugc\">Food Blog</a></li>\n<li><a href=\"http://demo.phlox.pro/default/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=8\" rel=\"nofollow ugc\">Default</a></li>\n<li><a href=\"http://demo.phlox.pro/coming-soon-1/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=37\" rel=\"nofollow ugc\">Coming Soon Red</a></li>\n<li><a href=\"http://demo.phlox.pro/coming-soon-2/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_campaign=wporg-profile&amp;utm_term=38\" rel=\"nofollow ugc\">Coming Soon Galaxy</a></li>\n</ul>\n<h4>Compatible Browsers</h4>\n<ul>\n<li>IE9+</li>\n<li>Firefox</li>\n<li>Safari</li>\n<li>Opera</li>\n<li>Chrome</li>\n<li>iOS browser</li>\n<li>Android browser</li>\n</ul>\n<h4>Documentations</h4>\n<p>If you have any question about working with &#8220;Phlox Core Elements&#8221;, you can take a look at <a href=\"https://docs.phlox.pro/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_content=auxin-elements-doc&amp;utm_term=documentation\" rel=\"nofollow ugc\">online documentations</a></p>\n<h4>Translation</h4>\n<p>You can start translating this plugin from here: <a href=\"https://translate.wordpress.org/projects/wp-plugins/auxin-elements\" rel=\"nofollow ugc\">online translation service</a>.</p>\n\";s:12:\"installation\";s:1677:\"<h4>Minimum Requirements</h4>\n<ul>\n<li>WordPress 4.6 or greater</li>\n<li>PHP version 5.6.0 or greater</li>\n<li>MySQL version 5.0 or greater</li>\n</ul>\n<p><strong>This plugin works the best in <a href=\"http://phlox.pro/\" rel=\"nofollow ugc\">Phlox Theme</a></strong></p>\n<h4>Automatic installation (easiest way)</h4>\n<p>To do an automatic install of Phlox Core Elements, log in to your WordPress dashboard, navigate to the Plugins menu and click Add New.</p>\n<p>In the search field type &#8220;Phlox Core Elements&#8221; and click Search Plugins. Once you have found it you can install it by simply clicking &#8220;Install Now&#8221;.</p>\n<h4>Manual installation</h4>\n<p><strong>Uploading in WordPress Dashboard</strong></p>\n<ol>\n<li>Download <code>auxin-elements.zip</code></li>\n<li>Navigate to the &#8216;Add New&#8217; in the plugins dashboard</li>\n<li>Navigate to the &#8216;Upload&#8217; area</li>\n<li>Select <code>auxin-elements.zip</code> from your computer</li>\n<li>Click &#8216;Install Now&#8217;</li>\n<li>Activate the plugin in the Plugin dashboard</li>\n</ol>\n<p><strong>Using FTP</strong></p>\n<ol>\n<li>Download <code>auxin-elements.zip</code></li>\n<li>Extract the <code>auxin-elements</code> directory to your computer</li>\n<li>Upload the <code>auxin-elements</code> directory to the <code>/wp-content/plugins/</code> directory</li>\n<li>Activate the plugin in the Plugin dashboard</li>\n</ol>\n<p>The WordPress codex contains <a href=\"https://codex.wordpress.org/Managing_Plugins#Manual_Plugin_Installation\" rel=\"nofollow ugc\">instructions on how to install a WordPress plugin</a>.</p>\n<h4>Updating</h4>\n<p>You can use automatic update to update the plugin safely.</p>\n\";s:3:\"faq\";s:1027:\"\n<dt id=\"where%20can%20i%20find%20phlox%20core%20elements%20documentation%20and%20user%20guides\">\nWhere can I find Phlox Core Elements documentation and user guides\n</h4>\n<p>\n<p>If you have any question about working with &#8220;Phlox Core Elements&#8221;, you can take a look at <a href=\"https://docs.phlox.pro/?utm_source=wporg-auxin-elements&amp;utm_medium=wporg&amp;utm_content=auxin-elements-doc&amp;utm_term=documentation\" rel=\"nofollow ugc\">online documentations</a></p>\n<p>If you get stuck you can <a href=\"http://help.averta.net/\" rel=\"nofollow ugc\">ask your question here</a>.</p>\n</p>\n<dt id=\"will%20phlox%20core%20elements%20work%20with%20my%20theme%3F\">\nWill Phlox Core Elements work with my theme?\n</h4>\n<p>\n<p>No, Phlox Core Element only works on <a href=\"http://phlox.pro/\" rel=\"nofollow ugc\">Phlox Theme</a></p>\n</p>\n<dt id=\"where%20can%20i%20report%20bugs%3F\">\nWhere can I report bugs?\n</h4>\n<p>\n<p>Bugs can be reported in our <a href=\"https://docs.phlox.pro\" rel=\"nofollow ugc\">support forums</a>.</p>\n</p>\n\n\";s:9:\"changelog\";s:17634:\"<h4>Version 2.17.22 / (30.07.2026)</h4>\n<ul>\n<li>[Fix]: Addressed a low-severity security vulnerabilities</li>\n</ul>\n<h4>Version 2.17.21 / (06.07.2026)</h4>\n<ul>\n<li>[Fix]: Compatibility and full integration for wpforms added.</li>\n</ul>\n<h4>Version 2.17.16 / (09.05.2026)</h4>\n<ul>\n<li>[Fix]: Addressed two low-severity security vulnerabilities (CVE-2025-69016, CVE-2026-4291)</li>\n</ul>\n<h4>Version 2.17.15 / (24.01.2026)</h4>\n<ul>\n<li>[Fix]: An issue with choosing tag type in Elementor &#8220;modern heading&#8221; element fixed.</li>\n</ul>\n<h4>Version 2.17.13 / (27.12.2025)</h4>\n<ul>\n<li>[Improvement]: Improved the import of sliders while importing a demo.</li>\n</ul>\n<h4>Version 2.17.12 / (31.08.2025)</h4>\n<ul>\n<li>[Improvement]: Style generation improvement for footer and header sections.</li>\n</ul>\n<h4>Version 2.17.10 / (21.07.2025)</h4>\n<ul>\n<li>[Improvement]: Compatibility for Elementor 3.31 added.</li>\n</ul>\n<h4>Version 2.17.9 / (15.07.2025)</h4>\n<ul>\n<li>[Fix]: Fixed an issue with cropped image size on search result page.</li>\n</ul>\n<h4>Version 2.17.8 / (07.06.2025)</h4>\n<ul>\n<li>[Fix]: Fixed missing GIF placeholder causing 404 errors.</li>\n<li>[Fix]: Fixed accordion element title color not applying correctly.</li>\n<li>[Fix]: Fixed issue with importing popup template by Depicter.</li>\n</ul>\n<h4>Version 2.17.6 / (13.04.2025)</h4>\n<ul>\n<li>[Improvement]: Security improvements applied.</li>\n</ul>\n<h4>Version 2.17.0 / (07.02.2025)</h4>\n<ul>\n<li>[Improvement]: Minor security improvements applied.</li>\n</ul>\n<h4>Version 2.17.0 / (12.12.2024)</h4>\n<ul>\n<li>[Improvement]: Compatibility with Elementor 3.25.0 applied.</li>\n</ul>\n<h4>Version 2.16.4 / (02.10.2024)</h4>\n<ul>\n<li>[Improvement]: Minor security improvements applied.</li>\n</ul>\n<h4>Version 2.16.0 / (16.06.2024)</h4>\n<ul>\n<li>[Improvement]: Compatibility with latest version of WooCommerce applied.</li>\n</ul>\n<h4>Version 2.15.9 / (19.05.2024)</h4>\n<ul>\n<li>[Improvement]: Security improvements applied.</li>\n</ul>\n<h4>Version 2.15.0 / (23.11.2023)</h4>\n<ul>\n<li>[Improvement]: Improvements applied for Elementor.</li>\n<li>[Fix]: Better compatibility for WordPress 6.4.0.</li>\n</ul>\n<h4>Version 2.10.8 / (01.12.2022)</h4>\n<ul>\n<li>[Improvement]: Improvements applied to customizer options importer.</li>\n</ul>\n<h4>Version 2.10.5 / (11.10.2022)</h4>\n<ul>\n<li>[Fix]: An issue with Google map element fixed.</li>\n<li>[Improvement]: Some improvements applied to demo importer.</li>\n</ul>\n<h4>Version 2.10.1 / (22.08.2022)</h4>\n<ul>\n<li>[Fix]: An issue with import of background image for Depicter slider fixed.</li>\n<li>[Fix]: An issue with some notices while saving a page with Elementor fixed.</li>\n</ul>\n<h4>Version 2.9.5 / (24.04.2022)</h4>\n<ul>\n<li>[New]: Copy animation button added to Elementor context menu to copy and paste animations across elements.</li>\n<li>[Fix]: Deprecated notices of new version of Elementor fixed.</li>\n</ul>\n<h4>Version 2.9.4 / (23.01.2022)</h4>\n<ul>\n<li>[Fix]: An issue while creating a translation with Polylang plugin fixed.</li>\n</ul>\n<h4>Version 2.8.0 / (28.06.2021)</h4>\n<ul>\n<li>[New]: Integrating &#8220;Ti Wishlist plugin&#8221; for better wishlist features in shops.</li>\n<li>[New]: Integrating Elementor global colors in customizer for faster preview and customization experience.</li>\n<li>[New]: Adding dynamic tag for URL controller for linking to &#8220;Login&#8221; and &#8220;Singup&#8221; pages</li>\n</ul>\n<h4>Version 2.7.10 / (15.03.2021)</h4>\n<ul>\n<li>[Fix]: An issue with importing icons fixed in demo importer.</li>\n<li>[Improvement]: Improvements for shopping cart applied.</li>\n</ul>\n<h4>Version 2.6.14 / (09.09.2020)</h4>\n<ul>\n<li>[New]: New options for recent post elements added.</li>\n<li>[Fix]: Minor bug fixes and performance improvements.</li>\n</ul>\n<h4>Version 2.6.0 / (11.05.2020)</h4>\n<ul>\n<li>[New]: New option for changing the character limit of last breadcrumb text added.</li>\n<li>[Improvement]: Improvements for ajax add to cart applied.</li>\n<li>[Improvement]: Improvements for demo importer applied.</li>\n<li>[Fix]: A minor bug while using WordPress widgets in Elementor fixed.</li>\n</ul>\n<h4>Version 2.5.0 / (09.03.2020)</h4>\n<ul>\n<li>[Improvement]: Instagram link for staff Element added.</li>\n<li>[New]: Inline SVG option for Infobox element added.</li>\n<li>[Improvement]: Improvements in dark mode style of controllers for Elementor applied.</li>\n</ul>\n<h4>Version 2.4.18 / (03.02.2020)</h4>\n<ul>\n<li>[Improvement]: Some improvements for modern heading element applied.</li>\n<li>[Improvement]: Improvements for dark mode styles in Elementor panel applied.</li>\n</ul>\n<h4>Version 2.4.16 / (15.01.2020)</h4>\n<ul>\n<li>[Improvement]: Some improvements for testimonial element applied.</li>\n</ul>\n<h4>Version 2.4.12 / (01.11.2019)</h4>\n<ul>\n<li>[Improvement]: Some improvements for button element applied.</li>\n</ul>\n<h4>Version 2.4.11 / (03.10.2019)</h4>\n<ul>\n<li>[Fix]: An issue with mega menu fixed.</li>\n</ul>\n<h4>Version 2.4.8 / (25.08.2019)</h4>\n<ul>\n<li>[Improvement]: An issue while installing some bundled plugins fixed.</li>\n</ul>\n<h4>Version 2.4.7 / (01.08.2019)</h4>\n<ul>\n<li>[Improvement]: Improvements in the layout of templates kit.</li>\n</ul>\n<h4>Version 2.4.6 / (17.07.2019)</h4>\n<ul>\n<li>[Improvement]: Some style improvements in info box element applied.</li>\n<li>[Fix]: Fix an issue with genral headings typography fixed.</li>\n</ul>\n<h4>Version 2.4.4 / (11.06.2019)</h4>\n<ul>\n<li>[New]: Introducing single page builder.</li>\n<li>[Fix]: Minor bug fixes and performance improvements.</li>\n</ul>\n<h4>Version 2.4.2 / (05.05.2019)</h4>\n<ul>\n<li>[New]: Export and import options added to customizer.</li>\n<li>[Improvement]: Improvements in accordion element.</li>\n</ul>\n<h4>Version 2.4.1 / (30.04.2019)</h4>\n<ul>\n<li>[Fix]: An issue with importing some menu labels fixed.</li>\n<li>[Improvement]: Improvements in Phlox shop applied.</li>\n</ul>\n<h4>Version 2.3.11 / (03.01.2019)</h4>\n<ul>\n<li>[Improvement]: Changing the google analytic tracking option to tracking ID option.</li>\n<li>[New]: Addig new options for background and color hover effect for recent posts element.</li>\n<li>[Fix]: An issue with post formats fixed.</li>\n</ul>\n<h4>Version 2.3.7 / (06.01.2019)</h4>\n<ul>\n<li>[Fix]: New option for changing the border color of header section added to page options.</li>\n</ul>\n<h4>Version 2.3.6 / (27.12.2018)</h4>\n<ul>\n<li>[Fix]: Fixing an issue on gmap while zoom with scroll option is enabled.</li>\n<li>[New]: Adding preload option to post elements.</li>\n<li>[New]: Adding new preload preview options for image element.</li>\n</ul>\n<h4>Version 2.3.0 / (19.11.2018)</h4>\n<ul>\n<li>[Fix]: Fixing some undefined variables.</li>\n<li>[New]: Introducing Templates Kit Library.</li>\n<li>[New]: New preload options added to advanced image element, plus, adding max width and height options.</li>\n<li>[Fix]: Fixing an issue with lightbox features in image element.</li>\n<li>[Improvement]: Improvement in Info Box Element.</li>\n<li>[New]: Adding background hover options for Info Box Element.</li>\n<li>[Improvement]: Improvement in retrieving and displaying the list of demos applied.</li>\n<li>[New]: New top header options added to page options.</li>\n</ul>\n<h4>Version 2.2.22 / (16.09.2018)</h4>\n<ul>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.21 / (02.09.2018)</h4>\n<ul>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.20 / (23.08.2018)</h4>\n<ul>\n<li>[Fix]: Fixing some PHP notices while Elementor Pro was activated for the first time.</li>\n</ul>\n<h4>Version 2.2.18 / (20.08.2018)</h4>\n<ul>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.17 / (15.08.2018)</h4>\n<ul>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.16 / (09.08.2018)</h4>\n<ul>\n<li>[Fix]: An issue with importer fixed.</li>\n</ul>\n<h4>Version 2.2.13 / (31.07.2018)</h4>\n<ul>\n<li>[Improvement]: Improvement for Elementor page builder applied.</li>\n</ul>\n<h4>Version 2.2.12 / (21.07.2018)</h4>\n<ul>\n<li>[New]: Adding Custom CSS field to all Elementor elements.</li>\n<li>[New]: Adding video tutorials to Phlox dashboard.</li>\n</ul>\n<h4>Version 2.2.9 / (09.07.2018)</h4>\n<ul>\n<li>[Improvement]: Improvement in admin dashboard for displaying the latest changes.</li>\n<li>[Fix]: Some minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.8 / (05.07.2018)</h4>\n<ul>\n<li>[New]: Adding Custom CSS field to all Elementor elements.</li>\n<li>[New]: Adding video tutorials to Phlox dashboard.</li>\n<li>[Improvement]: Improvement in Phlox dashboard and demo importer.</li>\n<li>[Improvement]: Now you can filter the recommended plugins in Phlox dashboard.</li>\n<li>[Improvement]: Better plugin dependency management.</li>\n</ul>\n<h4>Version 2.2.7 / (27.06.2018)</h4>\n<ul>\n<li>[New]: Introducing brand new demo importer.</li>\n<li>[Improvement]: Improvement in responsive images.</li>\n<li>[Improvement]: Improvement in preloading images which result in faster page loading speed.</li>\n<li>[Fix]: An issue with Gallery element fixed.</li>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.3 / (14.06.2018)</h4>\n<ul>\n<li>[New]: New elements &#8220;Modern Heading&#8221; and &#8220;Mailchimp&#8221; for Elementor page builder added.</li>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 2.2.1 / (05.06.2018)</h4>\n<ul>\n<li>[New]: New element &#8220;Flexible List&#8221; for Elementor page builder added.</li>\n<li>[Fix]: An issue in SiteOrigin Text element fixed.</li>\n</ul>\n<h4>Version 2.2.0 / (31.05.2018)</h4>\n<ul>\n<li>[New]: Two new elements for Elementor page builder added (Accordion and Tabs).</li>\n<li>[Improvement]: Improvement in testimonial and staff elements for Elementor page builder.</li>\n</ul>\n<h4>Version 2.1.9 / (26.05.2018)</h4>\n<ul>\n<li>[New]: Three new elements for Elementor page builder added (Blockquote, Testimonial and Slider).</li>\n</ul>\n<h4>Version 2.1.8 / (24.05.2018)</h4>\n<ul>\n<li>[New]: Two new elements for Elementor page builder added (video and audio).</li>\n</ul>\n<h4>Version 2.1.7 / (23.05.2018)</h4>\n<ul>\n<li>[New]: 10 new elements for Elementor page builder added.</li>\n<li>[Improvement]: Under the hood improvements.</li>\n</ul>\n<h4>Version 2.1.6 / (16.05.2018)</h4>\n<ul>\n<li>[Improvement]: Improvement in image preloading.</li>\n<li>[Improvement]: Under the hood improvements.</li>\n</ul>\n<h4>Version 2.1.1 / (09.04.2018)</h4>\n<ul>\n<li>[Fix]: Bug fix and improvements for setup wizard.</li>\n<li>[New]: Introducing Recent Product Element for Woocommerce.</li>\n<li>[Improvement]: Make recent portfolios element compatible with ajax loadmore.</li>\n</ul>\n<h4>Version 2.0.9 / (13.03.2018)</h4>\n<ul>\n<li>[New]: Adding an option for marker icon in gmap element.</li>\n<li>[Fix]: Fixing a fatal error while saving the post with wordpress-seo enabled.</li>\n<li>[New]: Added star rating to testimonial element.</li>\n<li>[New]: Add a new meta option for disabling the header logo in a page.</li>\n<li>[Improvement]: Adding animation tab and options to Visual Composer.</li>\n<li>[Improvement]: Improvement in subtitle option in recent posts element.</li>\n</ul>\n<h4>Version 2.0.6 / (17.02.2018)</h4>\n<ul>\n<li>[Fix]: Fixed an issue with post slider that excludes the first blog post.</li>\n<li>[Fix]: The warning message in timeline and masonry blog layout fixed.</li>\n<li>[New]: Adding lazyload option for image element</li>\n</ul>\n<h4>Version 2.0.5 / (13.02.2018)</h4>\n<ul>\n<li>[New]: New options in permalink page for changing the default slug of taxonomies.</li>\n<li>[Fix]: A PHP warning in search page fixed.</li>\n<li>[New]: Adding some hooks to replace custom logo images on pages if custom logo was specified</li>\n<li>[New]: New Metafields For Header and footer options.</li>\n</ul>\n<h4>Version 2.0.0 / (23.01.2018)</h4>\n<ul>\n<li>[Improvement]: Improvement in setup wizard.</li>\n<li>[Improvement]: Optimization, improvement and new size options in image element.</li>\n<li>[Improvement]: Improvement in timeline element.</li>\n<li>[Improvement]: Improvement in custom post types.</li>\n<li>[Improvement]: Improvement in permalink options.</li>\n<li>[Improvement]: Adding visualization to testimonial templates.</li>\n<li>[Improvement]: Improvement in carousel elements.</li>\n<li>[Improvement]: A verification for WP image sizes added to ensure image size ratio is the same.</li>\n<li>[New]: New feature for switching the website to maintenance mode.</li>\n<li>[Fix]: The query monitor report on VC front end editor disabled.</li>\n<li>[New]: Custom search functionality and options added.</li>\n<li>[New]: Added options and functionality for custom 404 page.</li>\n</ul>\n<h4>Version 1.7.2 / (02.12.2017)</h4>\n<ul>\n<li>[New]: Secondary and optional logo image added for sticky header.</li>\n<li>[New]: Adding new option for header background color while header is sticky.</li>\n<li>[New]: Install plugins tab added to phlox welcome page.</li>\n<li>[New]: New element &#8220;Recent Post Tile Carousel&#8221; added.</li>\n<li>[New]: Link to setup wizard added to &#8216;quick access&#8217; section in admin footer.</li>\n<li>[Improvement]: The dropdown control for categories in SiteOrigin Page Builder improved.</li>\n<li>[Improvement]: Add video length markup in the custom playlist.</li>\n<li>[Fix]: An issue with &#8220;Instagram feed&#8221; widget fixed.</li>\n<li>[Fix]: An issue with GMap widget fixed.</li>\n</ul>\n<h4>Version 1.7.0 / (14.11.2017)</h4>\n<ul>\n<li>[Fix]: An issue with recent post elements on single post page fixed.</li>\n<li>[Fix]: Live preview for header action buttons while editing in customizer.</li>\n<li>[New]: Add new functionalities to WordPress video playlist.</li>\n<li>[New]: Tiny size is added to the divider element.</li>\n<li>[Fix]: An issue with missing date and time in recent post slider fixed.</li>\n<li>[Fix]: Tabs and accordion elements are removed from widgets list.</li>\n<li>[Fix]: A typo in testimonial name fixed.</li>\n<li>[Improvement]: Default load more type for recent grid element changed.</li>\n</ul>\n<h4>Version 1.6.4 / (1.11.2017)</h4>\n<ul>\n<li>[Improvement]: Major improvements for page title setting were applied.</li>\n<li>[Improvement]: Several improvements for setup wizard were applied.</li>\n</ul>\n<h4>Version 1.6.2 / (23.10.2017)</h4>\n<ul>\n<li>[Improvement]: Improvement and bug fix for setup wizard.</li>\n</ul>\n<h4>Version 1.6.0 / (11.10.2017)</h4>\n<ul>\n<li>[New]: Introducing setup Wizard for importing demo content and installing recommended plugins.</li>\n<li>[New]: New Testimonial Widget added</li>\n</ul>\n<h4>Version 1.5.2 / (18.09.2017)</h4>\n<ul>\n<li>[New]: Load more option and button for blog elements.</li>\n<li>[Fix]: Fixing the category field option in blog elements.</li>\n</ul>\n<h4>Version 1.5.0 / (29.08.2017)</h4>\n<ul>\n<li>[Fix]: Addressed a conflict with popup-maker plugin.</li>\n<li>[Fix]: Some minor bugs in Text Element fixed.</li>\n<li>[Improvement]: Under the hood improvements for recent post grid element.</li>\n<li>[New]: New animated loop loading for gallery added.</li>\n</ul>\n<h4>Version 1.4.2 / (10.08.2017)</h4>\n<ul>\n<li>[New]: Changelog section added to welcome page</li>\n<li>[Improvement]: Some improvements in custom permalink structures for Phlox themes</li>\n</ul>\n<h4>Version 1.4.1 / (06.08.2017)</h4>\n<ul>\n<li>[Improvement]: Custom CSS and JavaScript fields added to pages</li>\n</ul>\n<h4>Version 1.4.0 / (02.08.2017)</h4>\n<ul>\n<li>[Improvement]: Applying some changes based on latest changes in auxin framework</li>\n</ul>\n<h4>Version 1.3.10 / (21.06.2017)</h4>\n<ul>\n<li>[Improvement]: New changes for auxin framework applied</li>\n</ul>\n<h4>Version 1.3.2 / (15.01.2017)</h4>\n<ul>\n<li>[Improvement]: New option for defining google map api key added</li>\n</ul>\n<h4>Version 1.3.2 / (08.01.2017)</h4>\n<ul>\n<li>[New]: Introducing Before after slider element to show comparison between two images.</li>\n<li>[New]: New slider element &#8220;touch image slider&#8221; added, now you can insert any image as a slider in any page via page builder</li>\n<li>[New]: Introducing tiles layout for auxin gallery element</li>\n<li>[Improvement]: The latest post slider and grid carousel improved.</li>\n<li>[Improvement]: The Recent grid blog element improved.</li>\n<li>[Improvement]: Column option for grid and masonry elements.</li>\n<li>[Improvement]: The functionality of lightbox in image element lightbox improved</li>\n<li>[Fix]: Minor bugs fixed.</li>\n</ul>\n<h4>Version 1.3.1 / (20.12.2016)</h4>\n<ul>\n<li>[Improvement]: New styles and options added to code element</li>\n<li>[Improvement]: Adding responsive options to row and column shortcodes</li>\n<li>[fix]: icon_size attribute added to text shortcode handler</li>\n<li>[Fix]: Fixed an issue that result in malfunction for gallery</li>\n</ul>\n<h4>Version 1.3.0 / (1.12.2016)</h4>\n<ul>\n<li>[Improvement]: Improved image sizes in recent posts elements</li>\n<li>[Improvement]: For responsiveness of grid table element</li>\n<li>[New]: adding hover effect option for grid table layout</li>\n<li>[New]: New options and styles for Text element added</li>\n<li>[New]: New options and layout for recent grid post element added</li>\n<li>[Improvement]: Improvement in title bar</li>\n<li>[New]: Persian translation added</li>\n</ul>\n<h4>Version 1.2.0 / (9.11.2016)</h4>\n<ul>\n<li>[New]: Introducing masonry layout for blog</li>\n</ul>\n<h4>Version 1.1.0 / (22.10.2016)</h4>\n<ul>\n<li>[New]: Introducing blog timeline view</li>\n</ul>\n<h4>Version 1.0.9 / (6.10.2016)</h4>\n<ul>\n<li>[New]: New shortcodes and widgets added</li>\n</ul>\n<h4>Version 1.0.6 / (19.9.2016)</h4>\n<ul>\n<li>[New]: New features added</li>\n</ul>\n<h4>Version 1.0.3 / (31.8.2016)</h4>\n<ul>\n<li>[Update]: Description in profile page updated</li>\n</ul>\n<h4>Version 1.0.0 / (30.8.2016)</h4>\n<ul>\n<li>Initial release</li>\n</ul>\n\";s:11:\"screenshots\";s:2273:\"<ol><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-1.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-1.png?rev=1486570\" alt=\"Front end widgets\"></a><p>Front end widgets</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-2.jpg?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-2.jpg?rev=1486570\" alt=\"Sample of using elements on the page\"></a><p>Sample of using elements on the page</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-3.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-3.png?rev=1486570\" alt=\"Some of these elements on the footer\"></a><p>Some of these elements on the footer</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-4.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-4.png?rev=1486570\" alt=\"Some Dropcap elements styles\"></a><p>Some Dropcap elements styles</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-5.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-5.png?rev=1486570\" alt=\"User friendly back end elements options\"></a><p>User friendly back end elements options</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-6.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-6.png?rev=1486570\" alt=\"List of elements on the page to choose from\"></a><p>List of elements on the page to choose from</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-7.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-7.png?rev=1486570\" alt=\"List of widgets to choose from\"></a><p>List of widgets to choose from</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-8.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-8.png?rev=1486570\" alt=\"One click shortcode elements with its options\"></a><p>One click shortcode elements with its options</p></li><li><a href=\"https://ps.w.org/auxin-elements/assets/screenshot-9.png?rev=1486570\"><img src=\"https://ps.w.org/auxin-elements/assets/screenshot-9.png?rev=1486570\" alt=\"User friendly editing elements\"></a><p>User friendly editing elements</p></li></ol>\";s:7:\"reviews\";s:11339:\"<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">It&#039;s not as bad as others say...</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/keysuck/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/7545a548d31f733628975527edd94885c7b615d0d47d1cbe3eec98beb6423d64?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/7545a548d31f733628975527edd94885c7b615d0d47d1cbe3eec98beb6423d64?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/keysuck/\" class=\"reviewer-name\">keysuck</a> on <span class=\"review-date\">March 20, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Before I started using Phlox, I read so many mixed reviews, which made me undecisive and hesitant. However, this theme had the best portfolio feature for my use, so I bit the bullet and gave it a go. Maybe my website is too simple to unearth the underlying technical issues, but so far I like the simple, minimal design elements that Phlox offers and how expansive the portfolio is - great for archiving works by a graphic design &amp; printing agency.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">damages my website</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/johnjmg/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/9b5ff84e5479d9e18f80f2c1fd9a3b836e53f5131036b42e9379d53226c8a1e8?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/9b5ff84e5479d9e18f80f2c1fd9a3b836e53f5131036b42e9379d53226c8a1e8?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/johnjmg/\" class=\"reviewer-name\">johnjmg</a> on <span class=\"review-date\">July 16, 2024</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>damages my website</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">fatal error</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/giuliopanda/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/297dee0b57bcb468be3e30405ae68ca8baa272a04bc19d2780989fff457e5a74?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/297dee0b57bcb468be3e30405ae68ca8baa272a04bc19d2780989fff457e5a74?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/giuliopanda/\" class=\"reviewer-name\">giuliopanda</a> on <span class=\"review-date\">March 3, 2023</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>The theme stopped working overnight giving the error: fatal error: function auxin_kses doesn\'t exist.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Buggiest Plugin EVER</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/neomundi/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/f7bd42f568a3072330e28b0078a55abcb7fb818a41d534e0944dcbc804258e39?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/f7bd42f568a3072330e28b0078a55abcb7fb818a41d534e0944dcbc804258e39?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/neomundi/\" class=\"reviewer-name\">neomundi</a> on <span class=\"review-date\">June 27, 2022</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\">Always breaks my shop about monthly. DO NOT BUY ANY THEM WITH THIS PLUGIN.</div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Everything works great!</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/artgali/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/79c91fbf8d0a43aa78a3e5eb449cd6ed56b7339348456c0b1fc6a921c13c3815?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/79c91fbf8d0a43aa78a3e5eb449cd6ed56b7339348456c0b1fc6a921c13c3815?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/artgali/\" class=\"reviewer-name\">artgali</a> on <span class=\"review-date\">April 24, 2021</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\">I saw there were some negative reviews and just want to give my two cents here. I have built a website with the Phlox theme and elements and I am very happy with it. I never have any issues in my nearly one year of using the plugins or theme. There are never any copatibility issues with other plugins either.\n\nFrequent updates and fast, Averta makes sure the theme works with latest Wordpress changes in matter of hours/days!\nThey are an excellent developer that has made an excellent theme!\n</div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Buggy plugin</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/millionary/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/acd5404e26788c4ed5b03eabccd5521783704d0def776d2ed4627b6a6a18c054?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/acd5404e26788c4ed5b03eabccd5521783704d0def776d2ed4627b6a6a18c054?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/millionary/\" class=\"reviewer-name\">millionary</a> on <span class=\"review-date\">April 15, 2020</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\">This issue makes it unusable, and apparently nobody even cares to answer or give information in the issue:\nhttps://wordpress.org/support/topic/missing-auxin_general_post_types_category_slug-leads-to-php-fatal-error/#post-12679183</div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Breaks my new site running 5.3.2</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"1 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"1\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/johncarteroz/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/b1604ab6b992aac70ff8989b8c5293a1e7538dd01d36fd518c99a91bb42e6d61?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/b1604ab6b992aac70ff8989b8c5293a1e7538dd01d36fd518c99a91bb42e6d61?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/johncarteroz/\" class=\"reviewer-name\">johncarteroz</a> on <span class=\"review-date\">March 22, 2020</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\">Well, I have used the phlox core plugin before but this time round, it simply breaks my admin and I need to remove the plugin via FTP.\n\nI am raising a support ticket and will revise my review when resolved.\n\n***** UPDATE *****\nWell, another site and this time it breaks my Theme. (PhLox) config (it simply will not load any theme options).\n\nClearly I need theme options more than a few widgets...\n\nI de-activate, theme customisation works... I activate it... the theme breaks.\n\ntoo tired to wait for a solution...\n\nSeems to be very buggy!!!</div>\n</div>\n\";}s:17:\"short_description\";s:90:\"Powerful and comprehensive plugin that extends the functionality of Phlox Elementor theme.\";s:13:\"download_link\";s:65:\"https://downloads.wordpress.org/plugin/auxin-elements.2.17.22.zip\";s:14:\"upgrade_notice\";