INSERT INTO `wp_options` VALUES (185,'theme_mods_phlox','a:27:{i:0;b:0;s:20:\"last_checked_version\";s:7:\"2.17.22\";s:12:\"initial_date\";s:19:\"2026-09-10 09:17:44\";s:15:\"initial_version\";s:7:\"2.17.22\";s:18:\"nav_menu_locations\";a:3:{s:14:\"header-primary\";i:11;s:16:\"header-secondary\";i:5;s:6:\"footer\";i:6;}s:12:\"font_subsets\";s:0:\"\";s:9:\"font_urls\";a:1:{s:18:\"auxin-fonts-google\";s:80:\"//fonts.googleapis.com/css?family=Outfit:100,200,300,regular,500,600,700,800,900\";}s:17:\"custom_css_string\";s:5835:\"/* header-logo-width \n=========================*/\n.aux-logo-header .aux-logo-anchor{ max-width:80px; }\n/* header-logo-max-height-type \n=========================*/\n.aux-logo-header .aux-logo-anchor > img { max-height:85px; }\n/* elementor-color-primary \n=========================*/\n.aux-customize-preview.elementor-kit-6 {--e-global-color-primary: #6EC1E4;}\n/* elementor-color-secondary \n=========================*/\n.aux-customize-preview.elementor-kit-6 {--e-global-color-secondary: #54595F;}\n/* elementor-color-text \n=========================*/\n.aux-customize-preview.elementor-kit-6 {--e-global-color-text: #7A7A7A;}\n/* elementor-color-accent \n=========================*/\n.aux-customize-preview.elementor-kit-6 {--e-global-color-accent: #61CE70;}\n/* site-frame-background-color \n=========================*/\n@media screen and (min-width: 700px) { .aux-framed .aux-side-frames, body.aux-framed:after, .aux-framed .aux-side-frames:before, .aux-framed .aux-side-frames:after {background-color:#111111;}}\n/* sticky-header-color \n=========================*/\n.aux-elementor-header.aux-sticky .elementor-section-wrap > .elementor-section, .aux-elementor-header.aux-sticky [data-elementor-type=\"header\"] > .elementor-section { background-color:#FFFFFF !important; }\n/* site-header-container-scaled-height \n=========================*/\n.aux-top-sticky .site-header-section.aux-sticky .aux-fill .aux-menu-depth-0 > .aux-item-content, .aux-top-sticky .site-header-section.aux-sticky .aux-header-elements,.aux-elementor-header.aux-sticky [data-elementor-type=\"header\"] > .elementor-section > .elementor-container,.aux-elementor-header.aux-sticky .elementor-section-wrap > .elementor-section > .elementor-container { min-height:80px; }\n/* site-header-container-height \n=========================*/\n.site-header-section .aux-header-elements:not(.aux-vertical-menu-elements), .site-header-section .aux-fill .aux-menu-depth-0 > .aux-item-content { height:85px; }\n/* site-transparent-header-bgcolor \n=========================*/\n.site-header-section { background-color:#FFFFFF; }\n/* site-vertical-menu-background-color \n=========================*/\n.aux-vertical-menu-side { background-color:#FFF; }\n/* site-header-navigation-item-height \n=========================*/\n.site-header-section .aux-middle .aux-menu-depth-0 > .aux-item-content { height:60px; }\n/* site-mobile-header-toggle-button-color \n=========================*/\n.site-header-section .aux-header .aux-burger:before, .site-header-section .aux-header .aux-burger:after, .site-header-section .aux-header .aux-burger .mid-line { border-color:#3d3d3d; }\n/* site-menu-full-screen-background-color \n=========================*/\n#fs-menu-search:before { background-color:rgba(255, 255, 255, 0.95); }\n/* site-top-header-background-color \n=========================*/\n#top-header {background-color:#FFFFFF;}\n/* blog-post-share-button-icon-size \n=========================*/\n.single-post .aux-single-post-share span::before { font-size:10px; }\n/* post-title-bar-overlay-pattern-opacity \n=========================*/\n.single-post .aux-overlay-bg-hash::before { opacity:0.15; }\n/* page-title-bar-overlay-pattern-opacity \n=========================*/\n.page .aux-overlay-bg-hash::before { opacity:0.5; }\n/* subfooter-bar-layout-bg-color \n=========================*/\n.aux-subfooter-bar { background-color:#fafafa; }\n/* subfooter-bar-top-border-color \n=========================*/\n.aux-subfooter-bar { border-top:1px solid #EAEAEA; }\n/* subfooter-layout-bg-image-position \n=========================*/\n.aux-subfooter {background-position:center center;}\n/* subfooter-layout-bg-image-size \n=========================*/\n.aux-subfooter {background-size:cover;}\n/* subfooter-layout-bg-image-repeat \n=========================*/\n.aux-subfooter {background-repeat:no-repeat;}\n/* subfooter-top-border-color \n=========================*/\n.aux-subfooter { border-top:1px solid #EAEAEA; }\n/* site-footer-bg-color \n=========================*/\n.aux-site-footer {background-color:#1A1A1A;}\n/* footer-top-border-color \n=========================*/\n.aux-site-footer {border-top:1px solid #EAEAEA;}\n/* footer-top-border-width \n=========================*/\n.aux-site-footer { border-top-width:1px; }\n/* site-secondary-logo-max-height \n=========================*/\n.aux-logo-footer .aux-logo-anchor img { max-height:50px; }\n/* portfolio-single-share-button-icon-size \n=========================*/\n.single-portfolio .aux-single-portfolio-share span::before { font-size:10px; }\n/* portfolio-title-bar-overlay-pattern-opacity \n=========================*/\n.single-portfolio .aux-overlay-bg-hash::before { opacity:0.5; }\n/* portfolio-classic-entry-box-background-color \n=========================*/\n.post-type-archive-portfolio .aux-entry-boxed .entry-main { background-color:#FFFFFF; }\n/* portfolio-classic-entry-box-border-color \n=========================*/\n.post-type-archive-portfolio .aux-entry-boxed .entry-main { border-color:#EAEAEA !important; }\n/* portfolio-land-side-background-color \n=========================*/\n.post-type-archive-portfolio .aux-item-land .aux-land-side { background-color:#FFFFFF; }\n/* portfolio-land-side-border-color \n=========================*/\n.post-type-archive-portfolio .aux-item-land .aux-land-side { border-color:#EAEAEA !important; }\n/* body-typography \n=========================*/\nbody{ font-family:\'Outfit\'; } \n/* general-headi