INSERT INTO `wp_options` VALUES (233,'_elementor_onboarding_strings_en','a:2:{s:7:\"timeout\";i:1790197675;s:5:\"value\";s:5406:\"{\"common.continue\":\"Continue\",\"common.skip\":\"Skip\",\"common.back\":\"Back\",\"common.finish\":\"Finish\",\"common.loading\":\"Loading\\u2026\",\"common.upgrade\":\"Upgrade\",\"common.close_onboarding\":\"Close onboarding\",\"common.installed\":\"Installed\",\"common.recommended\":\"Recommended\",\"error.failed_mark_exit\":\"Failed to mark user exit.\",\"error.failed_complete_step\":\"Failed to complete step.\",\"error.pro_install_failed\":\"Couldn\'t install Elementor Pro. Please try again later\",\"error.theme_install_failed\":\"Theme installation didn\'t complete. Please try again later\",\"login.title\":\"Let\\u2019s get to work.\",\"login.sign_in\":\"Sign in to Elementor\",\"login.continue_another_way\":\"Continue another way\",\"login.continue_as_guest\":\"Continue as a guest\",\"steps.building_for.title\":\"Who are you building for?\",\"steps.building_for.greeting_with_name\":\"Hey %1$s %2$s Let\\u2019s get your site set up.\",\"steps.building_for.greeting_without_name\":\"Hey%s Let\\u2019s get your site set up.\",\"steps.building_for.option_myself\":\"Myself or someone I know\",\"steps.building_for.option_business\":\"My business or workplace\",\"steps.building_for.option_client\":\"A client\",\"steps.building_for.option_exploring\":\"Just exploring\",\"steps.site_about.title\":\"What is your site about?\",\"steps.site_about.subtitle\":\"Choose anything that applies.\",\"steps.site_about.option_small_med_business\":\"Small-Med Business\",\"steps.site_about.option_online_store\":\"Online store\",\"steps.site_about.option_company_site\":\"Company site\",\"steps.site_about.option_blog\":\"Blog\",\"steps.site_about.option_landing_page\":\"Landing page\",\"steps.site_about.option_booking\":\"Booking\",\"steps.site_about.option_organization\":\"Organization\",\"steps.site_about.option_other\":\"Other\",\"steps.site_about.greeting