INSERT INTO `wp_options` VALUES (1831,'edd_sl_44e7f8d2bcb8949d6deea0c4900fa9bd','a:2:{s:7:\"timeout\";i:1789675795;s:5:\"value\";s:156344:\"{\"name\":\"Animation Addons Pro\",\"new_version\":\"2.6.6\",\"stable_version\":\"2.6.6\",\"sections\":{\"description\":\"<p><strong>Animation Addons for Elementor is the ultimate GSAP-powered animation plugin, featuring 100+ exclusive widgets, 25+ advanced Elementor extensions, 2,000+ professionally designed page templates, 220+ fully built websites (including all inner pages), and 10,000+ modern, ready-to-use section templates.<\\/strong><\\/p>\\n<p>As the No.1 <strong><a href=\\\"https:\\/\\/animation-addons.com\\/\\\">WordPress Animation Plugin<\\/a><\\/strong>, it enables you to create fully animated websites with advanced <strong>GSAP functionality<\\/strong> \\u2014no coding required. Bring your designs to life with smooth animations, interactive effects, and seamless motion.\\n<a href=\\\"https:\\/\\/animation-addons.com\\/\\\">Check the Pro Version <\\/a>\\n<a href=\\\"https:\\/\\/animation-addons.com\\/section-templates\\/\\\">Explore 10,000+ Section Templates <\\/a>\\n<a href=\\\"https:\\/\\/animation-addons.com\\/starter-templates\\/\\\">Browse 220+ Pre-Built Websites<\\/a>\\n<a href=\\\"https:\\/\\/animation-addons.com\\/pricing\\/\\\">Buy Pro Now \\u2013 Get 70% Off!<\\/a><\\/p>\\n<p><a href=\\\"https:\\/\\/youtu.be\\/tRbvgq2gJF4\\\">https:\\/\\/youtu.be\\/tRbvgq2gJF4<\\/a><\\/p>\\n<p><strong>Animation Addons for Elementor<\\/strong> includes all essential website-building tools, such as the <strong>Custom Header &amp; Footer Builder, CPT Builder, Animation Builder, Single Page and Single Post Builder, Mega Menu Builder, Archive Page Builder, and 404 Builder<\\/strong>. Designed to be lightweight, it ensures fast page loading times for a seamless user experience.<\\/p>\\n<p><a href=\\\"https:\\/\\/youtu.be\\/LD2mr5dHEng\\\">https:\\/\\/youtu.be\\/LD2mr5dHEng<\\/a><\\/p>\\n<h3>Powerful GSAP Features for Advanced Animations<\\/h3>\\n<p>&#x1f31f; ScrollTrigger\\n&#x1f3a8; GSAP Animation Builder\\n&#x1f3ac; Preset Animation\\n&#x26a1; Smooth Scrolling\\n&#x1f310; <a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/horizontal-scroll\\/\\\">Horizontal Scrolling<\\/a>\\n&#x1f4cc; <a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/pin-elements\\/\\\">Sticky Elements<\\/a>\\n&#x23f3; Timeline-Based Animation\\n&#x2702;&#xfe0f; <a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/text-animation\\/\\\">Split Text Animation<\\/a>\\n&#x1f504; <a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-flip-box\\/\\\">Flip Animation<\\/a>\\n&#x1f6d2; Scroll To Animation\\n&#x1f5b1;&#xfe0f; Draggable Elements\\n&#x270d;&#xfe0f; <a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-gsap-drawsvg\\/\\\">DrawSVG Animation<\\/a>\\n&#x1f3a5; <a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-lottie\\/\\\">Lottie Animation<\\/a>\\n&#x1f5bc;&#xfe0f; SVG Animation\\n&#x1f504; Morph SVG\\n&#x27a1;&#xfe0f; Motion Path Animation\\n&#x1f4cf; Stagger Animation\\n&#x1f32a;&#xfe0f; Scroll Smoother\\n&#x1f30d; Parallax Effects\\n&#x1f3a5; <a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/nested-slider-widget-for-elementor\\/\\\">Nested Elements<\\/a>\\n&#x2712;&#xfe0f; Text Scramble Animation\\n&#x1f39e;&#xfe0f; Clip Path Animation\\n&#x1f39a;&#xfe0f; Advanced Easing Functions\\n&#x1f5b1;&#xfe0f; <a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/features\\/aae-cursor\\/\\\">Custom Cursor Effects<\\/a>\\n&#x1f4f8; Image Sequence Animation\\n&#x1f31f; Layered Animation<\\/p>\\n<h3>Key Features of Animation Addons for Elementor<\\/h3>\\n<p>&#x1f4dd; Live Copy Paste\\n&#x1f4dd; Live Section Download\\n&#x1f3d7;&#xfe0f; Header Builder\\n&#x1f9b6; Footer Builder\\n&#x1f30d; Dynamic Content\\n&#x1f50c; <a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/\\\">Elementor Extensions<\\/a>\\n&#x1f3a8; <a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/features\\/aae-preloader\\/\\\">Preloader<\\/a>\\n&#x1f5c2;&#xfe0f; Mega Menus\\n&#x2194;&#xfe0f; <a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/horizontal-scroll\\/\\\">Horizontal Scrolling<\\/a>\\n&#x2194;&#xfe0f; Motion Scroll Card\\n&#x1f501; Preset Animation\\n&#x1f6e0;&#xfe0f; <a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/post-type-builder\\/\\\">CPT Builder<\\/a>\\n&#x1f5bc;&#xfe0f; Icon Generator\\n&#x1f520; <a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/custom-fonts\\/\\\">Custom Font Uploader<\\/a>\\n&#x26a1; <a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/getting-started\\/how-to-import-starter-templates-from-animation-addons\\/\\\">One-Click Demo Imports<\\/a>\\n&#x26a1; <a href=\\\"https:\\/\\/animation-addons.com\\/page-templates\\/\\\">One-Click Page Imports<\\/a>\\n&#x2712;&#xfe0f; CodeSnippet\\n&#x1f30d; Loop Builder<\\/p>\\n<p>Animation Addons for Elementor is a game-changer in animation-focused web design. The blend of its advanced animations, customizable features, and unique functionality set it apart from competitors. Whether you\\u2019re a web developer, designer, agency owner, or website owner, the plugin caters to your holistic professional needs.<\\/p>\\n<h3>Animation Addons for Elementor: Must-Have Extensions for Enhanced Web Design<\\/h3>\\n<p>Once your website is designed with all the essential elements, enhance its functionality, animations, and appearance with our advanced extensions. Explore our carefully curated list of exclusive extensions that elevate your Elementor-powered site to the next level.<\\/p>\\n<h3>GSAP Extensions:<\\/h3>\\n**Smooth Scroller**: Allow users to navigate web pages more smoothly and naturally.\\n**[Animation](https:\\/\\/animation-addons.com\\/docs\\/gsap-extensions\\/animation-extension-for-elementor\\/)**: Implement diverse, advanced animations for a visually appealing website.\\n**[Pin Element](https:\\/\\/animation-addons.com\\/extensions\\/pin-elements\\/)**: Fix elements in a specific space during scrolling to keep them always visible.\\n**[Text Animation](https:\\/\\/animation-addons.com\\/extensions\\/text-animation\\/)**: Create smooth text effects to make headings and content more engaging.\\n**[Image Animation](https:\\/\\/animation-addons.com\\/extensions\\/image-animation\\/)**: Add dynamic animations to images to capture the user\'s attention.\\n**[Cursor Hover Effect](https:\\/\\/animation-addons.com\\/extensions\\/cursor-hover-effect\\/)**: Add unique hover animations based on the cursor to increase interactivity.\\n**[Hover Effect Image](https:\\/\\/animation-addons.com\\/extensions\\/image-hover-effect\\/)**: Implement hover-specific image transformations for a modern touch.\\n**[Cursor Move Effect](https:\\/\\/animation-addons.com\\/extensions\\/cursor-move-effect\\/)**: Add immersive animations based on cursor movement.\\n**[Horizontal ScrollTrigger](https:\\/\\/animation-addons.com\\/extensions\\/horizontal-scroll\\/)**: Create animations when the user performs horizontal scrolling.\\n**[DrawSVG](https:\\/\\/animation-addons.com\\/widgets\\/aae-gsap-drawsvg\\/)**: Reveal or hide the stroke of an SVG progressively.\\n**[Portfolio Filter](https:\\/\\/animation-addons.com\\/docs\\/gsap-extensions\\/portfolio-filter\\/)**: Implement animated filters to organize and showcase portfolio items.\\n**Animation Builder**: Design powerful animations visually\\u2014no coding needed. Bring your Elementor pages to life in minutes!\\n<h3>General Extensions:<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/code-snippet\\/\\\">CodeSnippet<\\/a><\\/strong>: Add custom CSS, JS or PHP right inside Elementor to fine-tune designs without extra plugins.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/custom-css\\/\\\">Custom CSS<\\/a><\\/strong>: Add custom CSS styles directly within Elementor for precise design control.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/wrapper-link\\/\\\">Wrapper Link<\\/a><\\/strong>: Transform entire container sections into clickable links for seamless navigation.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/pop-up\\/\\\">Popup<\\/a><\\/strong>: Create engaging popups to enhance user interaction and showcase important content.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/tilt-effect-extensions\\/\\\">Tilt Effect<\\/a><\\/strong>: Tilt an element based on the visitor\\u2019s mouse movement for a dynamic visual experience.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/extensions\\/advanced-tooltip\\/\\\">Advanced Tooltip<\\/a><\\/strong>: Display additional information about elements when users hover over them.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/custom-fonts\\/\\\">Custom Fonts<\\/a><\\/strong>: Integrate unique custom fonts to maintain a consistent brand identity.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/custom-icon\\/\\\">Custom Icon<\\/a><\\/strong>: Upload and use your own icon fonts, including IcoMoon, to keep your website perfectly on-brand.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/general-extensions\\/post-type-builder\\/\\\">Custom PostType<\\/a><\\/strong>: Create and manage custom post types easily without any coding\\u2014perfect for blogs, portfolios, or products.\\n<strong>Mega Menu<\\/strong>: Create a customizable, expansive mega menu for seamless navigation.<h3>Animation Addons For Elementor Widget List<\\/h3>Take your website design to the next level with 100+ Elementor widgets. Whether you need dynamic sliders, service boxes, headers, portfolios, progress bars, breadcrumbs, accordions, post-feature images, or excerpts, Animation Addons got you covered.<\\/p>\\n<h3>Header and Footer Widgets;<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-site-logo\\/\\\">Site Logo<\\/a><\\/strong>: Display the website\\u2019s logo prominently to establish brand identity and recognition.\\n<strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-nav-menu\\/\\\">Nav Menu<\\/a><\\/strong>: Present a collection of links or buttons that help users navigate different sections of the website easily.<\\/p>\\n<h3>Dynamic Widgets:<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/post-title\\/\\\">Post Title<\\/a><\\/strong>: Dynamically display the title of a specific post or page within the website\\u2019s layout.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/post-featured-image\\/\\\">Post Featured Image<\\/a><\\/strong>: Display the featured image associated with a specific post or page.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/post-excerpt\\/\\\">Post Excerpt<\\/a><\\/strong>: Show a summary or excerpt of a specific post or page.<\\/p>\\n<p><strong>Post Content<\\/strong>: Present the core content, including text, images, videos, and other multimedia elements.<\\/p>\\n<p><strong>Post Comments<\\/strong>: Enable users to leave comments, feedback, and engage in discussions on individual posts or pages.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/post-meta-info\\/\\\">Post Meta Info<\\/a><\\/strong>: Provide supplementary details about individual posts or pages.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/post-pagination\\/\\\">Post Pagination<\\/a><\\/strong>: Break down content into manageable pages, allowing users to browse multiple posts.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-social-share\\/\\\">Post Social Share<\\/a><\\/strong>: Enable social media sharing of individual posts or articles to expand reach and visibility.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-posts\\/\\\">Posts<\\/a><\\/strong>: Showcase a list of blog posts or custom post types in multiple unique styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/wcf-template\\/blog-archive\\/\\\">Archive Title<\\/a><\\/strong>: Dynamically display the title of an archive page based on specific criteria such as date, category, tag, or author.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-portfolio\\/\\\">Portfolio<\\/a><\\/strong>: Display pages, posts, and custom post types in a filterable grid.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/wcf-template\\/search-form\\/\\\">Search Form<\\/a><\\/strong>: Provide users with a simple and intuitive interface to input search queries and retrieve relevant results.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-search-query\\/\\\">Search Query<\\/a><\\/strong>: Display search results in real-time as users type their queries.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/dynamic-widgets\\/search-no-result\\/\\\">Search No Result<\\/a><\\/strong>: Offer helpful guidance and options when no relevant search results are found.<\\/p>\\n<h3>Form Widgets<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-contact-form-7\\/\\\">Contact Form 7<\\/a><\\/strong>: Customize Contact Form 7 forms to match specific needs.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-mailchimp\\\">Mailchimp<\\/a><\\/strong>: Enable users to add opt-in forms to collect emails.<\\/p>\\n<h3>Video Widgets<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-video-popup\\/\\\">Video Popup<\\/a><\\/strong>: Display a video in a popup to enhance engagement.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-video-box\\\">Video Box<\\/a><\\/strong>: Showcase external and self-hosted videos from various sources.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-video-box-slider\\/\\\">Video Box Slider<\\/a><\\/strong>: Create a slider with videos from multiple sources.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-video-mask\\/\\\">Video Mask<\\/a><\\/strong>: Apply transitions, visual effects, and isolate video elements.<\\/p>\\n<h3>Advanced Widgets<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-toggle-switch\\/\\\">Toggle Switcher<\\/a><\\/strong>: Allow users to toggle between two mutually exclusive states (on\\/off).<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-advanced-portfolio\\\">Advanced Portfolio<\\/a><\\/strong>: Add a responsive portfolio slider or grid to showcase images, videos, or projects<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-table-of-content\\\">Table of Contents<\\/a><\\/strong>: Generate a list of navigation links to different sections of a page.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-flip-box\\/\\\">Flip Box<\\/a><\\/strong>: Provide interactive design effects such as flip, slide, fade, zoom-in, and zoom-out.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-advanced-accordion\\/\\\">Advanced Accordion<\\/a><\\/strong>: Enable collapsible content sections for better organization.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-advanced-pricing-table\\/\\\">Advanced Pricing Table<\\/a><\\/strong>: Display structured pricing information effectively.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-filterable-gallery\\/\\\">Filterable Gallery<\\/a><\\/strong>: Create an attractive, well-organized image gallery.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-image-accordion\\/\\\">Image Accordion<\\/a><\\/strong>: Display a series of images interactively and compactly.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-scroll-elements\\/\\\">Scroll Elements<\\/a><\\/strong>: Implement scroll-driven interactions for enhanced engagement.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-breadcrumbs\\\">Breadcrumbs<\\/a><\\/strong>: Display the navigation path to the current page.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-author-box\\\">Author Box<\\/a><\\/strong>: Show detailed information about the author of a post or page.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-filterable-slider\\\">Filterable Slider<\\/a><\\/strong>: Allow users to filter data by removing unwanted content.<\\/p>\\n<h3>General Widgets<\\/h3>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-animated-titl\\\">Animated Title<\\/a><\\/strong>: Animate your titles with effects such as fade, character-based animation, word animation, text reveal, 3D movement, and more.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-animated-text\\\">Animated Text<\\/a><\\/strong>: Animate text with various effects, including fade, character-based animation, word animation, text reveal, and more.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-image-box\\\">Image Box<\\/a><\\/strong>: Present images with unique animations in five different styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-image-box-slider\\\">Image Box Slider<\\/a><\\/strong>: Showcase images in a slider with five different styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-image\\\">Image<\\/a><\\/strong>: Display images such as company logos, photos, or illustrations in PNG, JPEG, WebP, or GIF format.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/image-gallery-widget\\\">Image Gallery<\\/a><\\/strong>: Create an image gallery with multiple styles and animations.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-brand-slider\\\">Brand Slider<\\/a><\\/strong>: Showcase client or brand logos in a stylish slider with text and image options.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-text-hover-image\\\">Text Hover Image<\\/a><\\/strong>: Add a text overlay to an image on hover.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-counter\\\">Counter<\\/a><\\/strong>: Add an animated numbered counter to display statistics dynamically.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-icon-box\\\">Icon Box<\\/a><\\/strong>: Showcase information using icons, titles, and descriptions in multiple styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-testimonial\\\">Testimonial<\\/a><\\/strong>: Display client feedback with 15 unique styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/aae-button\\\">Button<\\/a><\\/strong>: Add modern buttons with seven different styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-image-comparison\\\">Image Compare<\\/a><\\/strong>: Compare two images side by side to highlight differences.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/aae-progress-bar\\\">Progress Bar<\\/a><\\/strong>: Display progress or completion status of tasks or processes in various styles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-social-icons\\\">Social Icons<\\/a><\\/strong>: Add social media icons that link to your profiles.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-team\\\">Team<\\/a><\\/strong>: Showcase your team in style to build credibility effortlessly.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-one-page-nav\\\">One Page Nav<\\/a><\\/strong>: Simplify navigation with a smooth scrolling effect.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-timeline\\\">Timeline<\\/a><\\/strong>: Create visually appealing timelines for events or personal journeys.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-tabs\\\">Tabs<\\/a><\\/strong>: Enhance navigation and improve user experience with tabbed content.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-services-tabs\\\">Services Tab<\\/a><\\/strong>: Present services effectively with multiple styling options.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-floating-elements\\\">Floating Elements<\\/a><\\/strong>: Add captivating animations like floating, moving, zooming in\\/out, and rotation.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/aae-event-slider\\\">Event Slider<\\/a><\\/strong>: Showcase special events with dynamic sliders.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/aae-content-slider\\\">Content Slider<\\/a><\\/strong>: Create seamless content sliders for showcasing information effectively.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-countdown\\/\\\">Countdown<\\/a><\\/strong>: Add countdowns to create excitement for upcoming events or promotions.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-typewriter\\/\\\">Typewriter<\\/a><\\/strong>: Display a typing effect to engage users dynamically.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/aae-animated-heading\\/\\\">Animated Heading<\\/a><\\/strong>: Create eye-catching and engaging animated headlines.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/advanced-widgets\\/scrollmotion-cards\\/\\\">Scrollmotion Cards<\\/a><\\/strong>: Add stunning scroll-triggered animated cards.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/widgets\\/nested-slider-widget-for-elementor\\/\\\">Nested Slider<\\/a><\\/strong>: Create advanced multi-layer sliders with smooth animations and full Elementor control.<\\/p>\\n<p><strong><a href=\\\"https:\\/\\/animation-addons.com\\/docs\\/advanced-widgets\\/vertical-marquee\\/\\\">Vertical Marquee<\\/a><\\/strong>: Add smooth, continuous vertical scrolling text or images to grab attention effortlessly.<h3>Animation Addons for Elementor: Key Features<\\/h3><\\/p>\\n<h3>Massive Website Template Library<\\/h3>\\n<p>Animation Addons for Elementor offers an extensive collection of high-quality templates, designed to streamline website creation. With <strong>220+ pre-built website templates<\\/strong>, you can launch a fully designed website in seconds using the <strong>one-click demo<\\/strong> import feature.<\\/p>\\n<p>&#x1f539; <strong>10,000+ Section Templates<\\/strong> \\u2013 Mix and match to create a unique design effortlessly.\\n&#x1f539; <strong>2,000+ Page Templates<\\/strong> \\u2013 Choose from a diverse range of ready-made pages to suit any niche.<\\/p>\\n<p>This template library is specifically crafted for developers, designers, and agencies to build professional websites <strong>without writing a single line of code<\\/strong>. &#x1f680;<\\/p>\\n<h3>GSAP Animation Features in Animation Addons<\\/h3>\\n<p>&#x1f680; Enhance your website with GSAP-powered animations in Animation Addons for Elementor. Create smooth motion effects, interactive scroll animations, dynamic text transitions, and stunning SVG effects\\u2014all without coding.<\\/p>\\n<p><strong>&#x1f3a8; Core Animation Features<\\/strong>\\n&#x1f539; Tweens, Timelines &amp; Keyframes\\n&#x1f539; Stagger, Delay &amp; Easing Effects\\n&#x1f539; Loop, Reverse &amp; Duration Control<\\/p>\\n<p><strong>&#x1f504; Scroll-Based Animations<\\/strong>\\n&#x1f538; ScrollTrigger \\u2013 Animate on scroll\\n&#x1f538; ScrollSmoother \\u2013 Enhance scrolling\\n&#x1f538; ScrollTo \\u2013 Smooth scroll navigation<\\/p>\\n<p><strong>&#x270f;&#xfe0f; SVG &amp; Shape Animations<\\/strong>\\n&#x1f7e2; MorphSVG \\u2013 Shape transformations\\n&#x1f7e2; DrawSVG \\u2013 Animated stroke effects\\n&#x1f7e2; MotionPath \\u2013 Custom path animations<\\/p>\\n<p><strong>&#x1f524; Text Animations<\\/strong>\\n&#x1f520; SplitText \\u2013 Break text into animations\\n&#x1f520; ScrambleText \\u2013 Dynamic text effects\\n&#x1f520; Text Move &amp; Invert \\u2013 Unique typography<\\/p>\\n<p><strong>&#x1f300; 3D &amp; Transform Effects<\\/strong>\\n&#x1f535; 3D Rotation, Scaling &amp; Spin\\n&#x1f535; Perspective &amp; Motion Enhancements<\\/p>\\n<p>&#x1f4a1; Unlock next-level animations with <strong>Animation Addons for Elementor!<\\/strong><\\/p>\\n<h3>100+ Elementor Widgets:<\\/h3>\\n<p>Unlock endless design possibilities with 100+ advanced Elementor widgets. From dynamic sliders, service boxes, and portfolio grids to progress bars, accordions, and featured post images, these widgets enhance user engagement and optimize website functionality without the need for coding.<\\/p>\\n<h3>Custom Animation Builder:<\\/h3>\\n<p>The Custom Animation Builder is a powerful tool that allows WordPress users to create stunning GSAP-powered animations without any coding. This intuitive builder integrates the full potential of GSAP (GreenSock Animation Platform), enabling you to craft smooth transitions, complex timelines, and advanced animations like never before. Key features include ScrollTrigger for scroll-based animations, MorphSVG for shape transformations, DrawSVG for dynamic SVG animations, SplitText for text effects, ScrambleText for engaging typography, ScrollSmoother for smooth page scrolling, and 3D Transformations for depth and perspective adjustments. With easy-to-use controls, the Custom Animation Builder gives you complete creative freedom to elevate your website\\u2019s design and interactivity without writing a single line of code.<\\/p>\\n<h3>Advanced Website Builders for Complete Customization<\\/h3>\\n<p><strong>Animation Addons for Elementor<\\/strong> provides powerful <strong>website builders<\\/strong> to design <strong>custom headers, footers, mega menus, archive pages, single post layouts, and popups<\\/strong> \\u2014without writing a single line of code. The <strong>Header &amp; Footer Builder<\\/strong> enables seamless branding with logos, menus, and call-to-action buttons, while the <strong>Mega Menu Builder<\\/strong> creates expandable, visually rich navigation with icons and animations.<\\/p>\\n<p>The <strong>Archive Page Builder<\\/strong> simplifies designing category, taxonomy, and tag archive templates, while the <strong>Single Page &amp; Post Builder<\\/strong> gives full control over content structure and animations. Additionally, the <strong>Popup Builder<\\/strong> helps craft high-converting, fully customizable pop-ups with advanced design and targeting options. These intuitive tools make website building effortless in Elementor!<\\/p>\\n<h3>Smooth Scrolling Effects:<\\/h3>\\n<p>Add a sleek and modern touch to your scrolling experience with the smooth scrolling feature of the addons. It\\u2019s ideal for long-form content or one-page designs, where things move from one section. Smooth scrolling significantly minimizes sudden jumps and improves flow.<\\/p>\\n<h3>Pin Elements:<\\/h3>\\n<p>Use the pinning elements to keep the important content always visible. This Elementor animation plugin ensures that key elements like a sticky navigation bar, promotional banner, or call-to-action button remain accessible as users scroll through your site.<\\/p>\\n<h3>One Page Scroll:<\\/h3>\\n<p>Create modern, one-page websites with the one-page scroll feature of the Animation Addons. This tool lets you build fluid navigation with easy transitions as you can scroll through an entire page at once.<h3>Why Use Animation Addons for Elementor?<\\/h3><\\/p>\\n<h3>Custom CSS:<\\/h3>\\n<p>Animation Addons for Elementor empower you to take full control in custom CSS. You can personalize your website just the way you like by changing layouts, colors, animations, and typography. It offers pinpoint accuracy to build a website that meets your specific vision.<\\/p>\\n<h3>Completely Customizable:<\\/h3>\\n<p>Experience unrivaled versatility with fully customizable design options. A website built with the help of the comprehensive customizability of Animation Addons for Elementor is always incredibly beautiful to look at.<\\/p>\\n<h3>Multi-Widget Area:<\\/h3>\\n<p>Animation Addons for Elementor focuses on maximizing your website\\u2019s overall functionality with a multi-widget area. You can insert multiple widgets in different areas of your website anytime you desire<\\/p>\\n<h3>Instant Loading:<\\/h3>\\n<p>Animation Addons for Elementor is built to minimize delays and let you experience immediate loading times. Unlike other animation plugins, our plugin is super fast and SEO-friendly.  With a view to keeping visitors engaged and reducing bounce rates, the plugin will make your content appear quickly.<\\/p>\\n<p>This plugin using the modified version of [WP import 2.0] (<a href=\\\"https:\\/\\/github.com\\/humanmade\\/WordPress-Importer\\\">https:\\/\\/github.com\\/humanmade\\/WordPress-Importer<\\/a>).<h3>External Services<\\/h3>We use the Themecrowdy API for one-click import of Elementor sites and section templates.\\nOur Mailchimp widget connects to Mailchimp\\u2019s API.\\nSubscribing is optional\\u2014no data is collected unless you opt in.<h3>Source Code<\\/h3>\\nSee the unminified JS and CSS in our public repo: <a href=\\\"https:\\/\\/github.com\\/Wealcoder\\/animation-addons-for-elementor\\/tree\\/dashboard\\/assets\\/src\\\">GitHub Repository<\\/a>.<\\/p>\",\"installation\":\"<h4> Minimum Requirements <\\/h4>\\n<ul>\\n<li>WordPress 6.5 or greater<\\/li>\\n<li>PHP version 7.4 or greater<\\/li>\\n<li>MySQL version 5.0 or greater<\\/li>\\n<\\/ul>\\n<h4> Recommended Requirements <\\/h4>\\n<ul>\\n<li>PHP version 8.3 or greater<\\/li>\\n<li>MySQL version 5.7 or greater<\\/li>\\n<li>WordPress Memory limit of 128 MB or greater (1024 MB or higher is preferred)\\n= Installation =\\nNote: This plugin requires Elementor to function. Please ensure Elementor is installed and activated before proceeding.<\\/li>\\n<\\/ul>\\n<ol>\\n<li>Install the plugin directly from the WordPress Plugins screen, or manually upload the plugin files to \\/wp-content\\/plugins\\/animation-addons directory.<\\/li>\\n<li>Activate the plugin from the Plugins section in your WordPress dashboard.<\\/li>\\n<li>Access all settings via the admin sidebar under Animation Addons.<\\/li>\\n<li>Find all widgets categorized as AAE pro, AAE, AAE Header &amp; Footer, AAE Archive, AAE Single, AAE Search inside the Elementor editor.<\\/li>\\n<\\/ol>\\n<p>For any questions, visit our FAQ page or reach out via our Contact Form. &#x1f680;<\\/p>\",\"changelog\":\"<p>= &#x1f300; Animation Addons for Elementor v2.6.3 \\u2013 01 April 2026<\\/p>\\n<pre><code>- Fixed: Issue with Live Copy.\\n- Fixed: Scroll to Top feature not working when Scroll Smoother was enabled. Now working correctly.\\n- Improved: Enhanced performance on both the builder and frontend.<\\/code><\\/pre>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.6 \\u2013 01 Dec 2025<\\/p>\\n<pre><code>- **Fix: Widget** - Loop grid style\\n- **Fix: Widget** - Youtube video\\n- **Fix: Widget** - Grid hover post responsive<\\/code><\\/pre>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.5 \\u2013 19 November 2025<\\/p>\\n<ul>\\n<li><strong>Feature:<\\/strong> Add new widget Loop Builder<\\/li>\\n<li><strong>Feature:<\\/strong> Add Dynamic Tag support in several widgets<\\/li>\\n<li><strong>Feature:<\\/strong> Add new controls in several widgets<\\/li>\\n<li><strong>Feature:<\\/strong> Add Current template Names in admin bar<\\/li>\\n<li><strong>Feature:<\\/strong> Add new Tag support in Extension Code Snippet HTML Editor<\\/li>\\n<li><strong>Fix: Extension<\\/strong> - Popup template and script issues<\\/li>\\n<li><strong>Fix: Extension<\\/strong> - Code Snippet Code Editor issues<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Toggle style and responsive issue<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Breadcrumb link and category link and name issue<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Image Box link issue<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Advanced Button style issue<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Nested Slider Pagination Control issues<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Brand Slider Responsive and image control issues<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Author Box link issue<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Post Ratings form issues<\\/li>\\n<li><strong>Fix: Widget<\\/strong> - Advanced Accordion image issue<\\/li>\\n<li><strong>Enhancement:<\\/strong> Remove unused code and Update code to the latest version php<\\/li>\\n<li><strong>Enhancement:<\\/strong> Compatible some code with WordPress 6.8 Coding Standards<\\/li>\\n<li><strong>Security:<\\/strong> Fix some nonce security issues<\\/li>\\n<li><strong>Security:<\\/strong> Fix some sanitizing and escaping issues<\\/li>\\n<li><strong>Added:<\\/strong> 15+ RTL Website templates <\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.4 \\u2013 06 November 2025<\\/p>\\n<pre><code>  -&#x1f3a8; **Added:** BlackFriday Offer  <\\/code><\\/pre>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.3 \\u2013 02 November 2025<\\/p>\\n<ul>\\n<li>\\n<p>&#x1fa9f; <strong>Offcanvas Widget:<\\/strong> Added new control options, updated markup for better flexibility, optimized CSS, and replaced jQuery with lightweight JavaScript for enhanced speed.<\\/p>\\n<\\/li>\\n<li>\\n<p>&#x1f4f1;<strong>Nav Menu Widget:<\\/strong><\\/p>\\n<ul>\\n<li><strong>Added<\\/strong> new control panel for customization.<\\/li>\\n<li><strong>Fixed<\\/strong> mobile menu click issue on devices under 767px by reloading JavaScript dynamically.<\\/li>\\n<li><strong>Converted<\\/strong> jQuery logic to pure JavaScript for improved performance.<\\/li>\\n<\\/ul>\\n<\\/li>\\n<li>\\n<p>&#x1f5bc;&#xfe0f; <strong>Image Accordion Widget:<\\/strong> Fixed functionality issues and completely refactored to vanilla JavaScript.<\\/p>\\n<\\/li>\\n<li>\\n<p>&#x1f518; <strong>Toggle Switcher:<\\/strong> Resolved toggle issues and refactored to pure JavaScript.<\\/p>\\n<\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.2 \\u2013 27 October 2025<\\/p>\\n<ul>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Dashboard ScrollSmother Settings  <\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.1 \\u2013 26 October 2025<\\/p>\\n<ul>\\n<li>&#x1f9e9; <strong>Added:<\\/strong> Dashboard new widget  <\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.4.0 \\u2013 23 October 2025<\\/p>\\n<ul>\\n<li>&#x1f9e9; <strong>Improved:<\\/strong> Dashboard interface<\\/li>\\n<li>&#x1f9e9; <strong>Improved:<\\/strong> Notice interface<\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.3.15 \\u2013 13 October 2025<\\/p>\\n<ul>\\n<li>&#x1f9e9; <strong>Fixed:<\\/strong> Resolved js on demand object<\\/li>\\n<\\/ul>\\n<p>= &#x1f300; Animation Addons for Elementor v2.3.14 \\u2013 12 October 2025<\\/p>\\n<ul>\\n<li>&#x26a1; <strong>Improved:<\\/strong> On-demand JS loading for <strong>Contact Form 7<\\/strong>, <strong>Toggle Switcher<\\/strong>, and <strong>Counter<\\/strong> widgets for faster performance.  <\\/li>\\n<li>&#x1f4e6; <strong>Improved:<\\/strong> <strong>Section Import Library<\\/strong> for smoother and more efficient section imports.  <\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Enhanced <strong>UX for the plugin dashboard<\\/strong> with a cleaner and more user-friendly interface.  <\\/li>\\n<li>&#x1f9e9; <strong>Fixed:<\\/strong> Resolved <strong>page import notice issue<\\/strong> for a better importing experience. <\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.13 \\u2013 24 September 2025 <\\/h4>\\n<ul>\\n<li>&#x1f195; Added: 660+ Pages in Page importer <\\/li>\\n<li>&#x270f;&#xfe0f; Improved: Code Snippet design and functionality <\\/li>\\n<li>&#x270f;&#xfe0f; Improved: Section Import Library,<\\/li>\\n<li>&#x1f3a8; Fixed: Native Sticky Header using smoother options<\\/li>\\n<li>&#x1f3a8; Fixed: ThemeBuilder post-singulars condition<\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.12 \\u2013 02 September 2025 <\\/h4>\\n<ul>\\n<li>&#x1f3a8; Fixed: Toggle Widget for smoother interaction and better user experience<\\/li>\\n<li>&#x1f3a8; Fixed: Mailchimp Widget subscribing issue to ensure seamless email marketing integration<\\/li>\\n<li>&#x1f3a8; Fixed: Nested Element editor loading issue for faster, stable page building<\\/li>\\n<li>&#x1f195; Added: Code Snippet visibility option to give you more control and flexibility in your projects<\\/li>\\n<li>&#x270f;&#xfe0f; Improved: Dashboard Starter Template design and filter for easier access to 220+ websites &amp; 10,000+ sections<\\/li>\\n<\\/ul>\\n<p>= Animation Addons for Elementor v2.3.11 \\u2013 19 august 2025 = <\\/p>\\n<ul>\\n<li>&#x1f195; <strong>Added:<\\/strong> Starter Template Menu<\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Mobile navigation overlay issue for smoother user experience<\\/li>\\n<li>&#x1f195; <strong>Added:<\\/strong> Code Snippet extension, <\\/li>\\n<li>&#x270f;&#xfe0f; <strong>Improved<\\/strong> Dashboard widget docs<\\/li>\\n<\\/ul>\\n<p>= Animation Addons for Elementor v2.3.10 \\u2013 11 august 2025 = <\\/p>\\n<ul>\\n<li>&#x1f195; <strong>Added:<\\/strong> 20+ premium widgets \\u2014 now completely free for all users!<\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Mobile navigation overlay issue for smoother user experience<\\/li>\\n<li>&#x1f195; <strong>Added:<\\/strong> New Popup trigger \\u2014 show popups on mouse leave to boost conversions<\\/li>\\n<li>&#x270f;&#xfe0f; <strong>Improved<\\/strong> Renamed \\u201cPin\\u201d extension to \\u201cSticky\\u201d for clearer usability and better user understanding<\\/li>\\n<\\/ul>\\n<p>= Animation Addons for Elementor v2.3.9 \\u2013 18 july 2025 = <\\/p>\\n<ul>\\n<li>&#x1f3a8; <strong>Update:<\\/strong> Documentation with setup and usage guides for the new widgets.<\\/li>\\n<li>&#x1f3a8; <strong>Optimize:<\\/strong> Faster, leaner JavaScript for both editor and frontend.<\\/li>\\n<li>&#x1f195; <strong>Added:<\\/strong> Rating widget to showcase reviews and user feedback.<\\/li>\\n<li>&#x1f195; <strong>Added:<\\/strong> Breadcrumbs widget for better site navigation in Elementor.<\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.8 \\u2013 17 july 2025 <\\/h4>\\n<ul>\\n<li>&#x1f195; <strong>Added:<\\/strong> ClickPop Widget for header<\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Starter Templates step  <\\/li>\\n<li>&#x1f3a8; <strong>Update:<\\/strong> Countdown widget css<\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.7 \\u2013 03 july 2025 <\\/h4>\\n<ul>\\n<li>&#x1f195; <strong>Added:<\\/strong> PopUp Builder Option<\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Dashboard name issue<\\/li>\\n<li>&#x1f3a8; <strong>Update:<\\/strong> meta style option<\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.6 \\u2013 01 july 2025 <\\/h4>\\n<ul>\\n<li>&#x1f195; <strong>Added:<\\/strong> New title show control in meta widget <\\/li>\\n<li>&#x1f3a8; <strong>Fixed:<\\/strong> Change template library icon<\\/li>\\n<li>&#x1f3a8; <strong>Update:<\\/strong> Community group link update<\\/li>\\n<\\/ul>\\n<h4> Animation Addons for Elementor v2.3.5 \\u2013 19 june 2025 <\\/h4>\\n<ul>\\n<li>&#x1f195; <strong>optimize:<\\/strong> Optimize Hotspot widget 