INSERT INTO `wp_posts` VALUES (16,1,'2026-09-10 12:53:28','2026-09-10 09:53:28','If several languages coalesce, the grammar of the resulting language is more simple and regular than that of the individual languages. The new common language will be more simple and regular than the existing European languages. It will be as simple as Occidental; in fact, it will be Occidental.','Montain and Winter Cold Weather','','trash','open','open','','montain-and-winter-cold-weather__trashed','','','2026-09-21 12:11:08','2026-09-21 09:11:08','',0,'http://thirdwebsite.local/?p=16',0,'post','',0);
INSERT INTO `wp_posts` VALUES (17,1,'2026-09-10 12:53:28','2026-09-10 09:53:28','The new common language will be more simple and regular than the existing European languages. It will be as simple as Occidental; in fact, it will be Occidental. To an English person, it will seem like simplified English, as a skeptical Cambridge friend of mine told me what Occidental is. The European languages are members of the same family.','Serious Problems with Cables in CIty','','trash','open','open','','serious-problems-with-cables-in-city__trashed','','','2026-09-21 12:11:08','2026-09-21 09:11:08','',0,'http://thirdwebsite.local/?p=17',0,'post','',0);
INSERT INTO `wp_posts` VALUES (18,1,'2026-09-10 12:53:28','2026-09-10 09:53:28','The new common language will be more simple and regular than the existing European languages. It will be as simple as Occidental; in fact, it will be Occidental. To an English person, it will seem like simplified English, as a skeptical Cambridge friend of mine told me what Occidental is. The European languages are members of the same family.','Road to Eye-catching Landscape','','trash','open','open','','road-to-eye-catching-landscape__trashed','','','2026-09-21 12:11:09','2026-09-21 09:11:09','',0,'http://thirdwebsite.local/?p=18',0,'post','',0);
