INSERT INTO `wp_posts` VALUES (611,1,'2026-09-19 13:44:54','2026-09-19 10:44:54','<img width=\"413\" height=\"413\" src=\"http://thirdwebsite.local/wp-content/uploads/2026/09/anim-2.png\" alt=\"\" srcset=\"http://thirdwebsite.local/wp-content/uploads/2026/09/anim-2.png 413w, http://thirdwebsite.local/wp-content/uploads/2026/09/anim-2-300x300.png 300w, http://thirdwebsite.local/wp-content/uploads/2026/09/anim-2-150x150.png 150w\" sizes=\"(max-width: 413px) 100vw, 413px\" />																					<a role=\"button\">\n									Get Started\n					</a>\n		<h3>\n									<b>Exploratory data analysis</b>\n									<b>Real-time data score analysis</b>\n									<b>Tailored pricing plans</b>\n			I		\n		</h3>\n		<h3>\n							Digital Age Adventure In\n									<b>Search</b>\n									<b>Results</b>\n		</h3>\n				<p>We offer flexible pricing plans so that our clients can take advantage of services.</p>			    \n                    <a href=\"http://Contact%20us\">\nGet Started for Free                \n            </a>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M464 64H48C21.49 64 0 85.49 0 112v288c0 26.51 21.49 48 48 48h416c26.51 0 48-21.49 48-48V112c0-26.51-21.49-48-48-48zm0 48v40.805c-22.422 18.259-58.168 46.651-134.587 106.49-16.841 13.247-50.201 45.072-73.413 44.701-23.208.375-56.579-31.459-73.413-44.701C106.18 199.465 70.425 171.067 48 152.805V112h416zM48 400V214.398c22.914 18.251 55.409 43.862 104.938 82.646 21.857 17.205 60.134 55.186 103.062 54.955 42.717.231 80.509-37.199 103.053-54.947 49.528-38.783 82.032-64.401 104.947-82.653V400H48z\"></path></svg>				\n									<h3>\n							startdomain.com						\n					</h3>\n																	<img width=\"1220\" height=\"1366\" src=\"http://thirdwebsite.local/wp-content/uploads/2026/09/hero-image.webp\" alt=\"\" />																										<img width=\"708\" height=\"174\" src=\"http://thirdwebsite.local/wp-content/uploads/2026/09/card-6-Q8UPFNA.webp\" alt=\"\" />														